package io.earthplatform.minecraft.visual;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class NativeDistanceCpuBudgetTest {
 @Test void reservationsAcrossGenerationsStayChargedUntilPhysicalDrain(){var b=new NativeDistanceCpuBudget(NativeDistanceCpuBudget.MAX_BYTES);var a=b.reserve(NativeDistanceCpuBudget.Pool.SOURCE,96L<<20);assertThrows(IllegalStateException.class,()->b.reserve(NativeDistanceCpuBudget.Pool.SOURCE,1));assertEquals(96L<<20,b.evidence().bytes());a.releaseAfterPhysicalDrain();a.releaseAfterPhysicalDrain();assertEquals(0,b.evidence().bytes());}
 @Test void aggregateRefusesEvenWhenBothPoolsIndividuallyFit(){var b=new NativeDistanceCpuBudget(100L<<20);var source=b.reserve(NativeDistanceCpuBudget.Pool.SOURCE,96L<<20);assertThrows(IllegalStateException.class,()->b.reserve(NativeDistanceCpuBudget.Pool.DH_RESULTS,5L<<20));assertEquals(96L<<20,b.evidence().bytes());var tail=b.reserve(NativeDistanceCpuBudget.Pool.WORKER_UPLOAD,4L<<20);assertEquals(100L<<20,b.evidence().peakBytes());tail.releaseAfterPhysicalDrain();source.releaseAfterPhysicalDrain();}
 @Test void allEightPhysicalPoolsShareOneGlobalCeiling(){var b=new NativeDistanceCpuBudget(NativeDistanceCpuBudget.MAX_BYTES);var tickets=new java.util.ArrayList<NativeDistanceCpuBudget.Reservation>();for(var p:NativeDistanceCpuBudget.Pool.values())tickets.add(b.reserve(p,p.limit()));assertEquals(NativeDistanceCpuBudget.MAX_BYTES,b.evidence().bytes());assertThrows(IllegalStateException.class,()->b.reserve(NativeDistanceCpuBudget.Pool.OWNER_METADATA,1));for(var t:tickets)t.releaseAfterPhysicalDrain();assertEquals(0,b.evidence().reservations());}
 @Test void crossThreadPhysicalReleaseIsSynchronized()throws Exception{var b=new NativeDistanceCpuBudget(1024);var t=b.reserve(NativeDistanceCpuBudget.Pool.WORKER_UPLOAD,1024);Thread worker=new Thread(t::releaseAfterPhysicalDrain);worker.start();worker.join();assertEquals(0,b.evidence().bytes());assertThrows(IllegalArgumentException.class,()->b.reserve(NativeDistanceCpuBudget.Pool.PLAN,-1));}
}
